mapper.select:
SELECT s.id, s.ledger_id, s.asset_id, s.snapshot_month, s.asset_code, s.asset_name, s.category_name, s.department_name, s.entry_date, s.original_value, s.standard_life_months, s.monthly_depreciation, s.accumulated_depreciation, s.net_value, s.months_used, s.current_user_name, s.current_user_employee_no, s.current_user_department, s.asset_status, s.created_at FROM asset_ledger_snapshot s WHERE 1=1
AND s.snapshot_month = #{param.snapshotMonth}
AND s.category_name = #{param.categoryId}
AND s.department_name = #{param.departmentId}
ORDER BY s.id DESC
